form: scale(0);\n  transform: scale(0);\n}\n.works-item .overlay::before {\n  border: 1px solid #f7f2e7;\n  bottom: 15px;\n  content: \"\";\n  left: 15px;\n  position: absolute;\n  right: 15px;\n  top: 15px;\n}\n.works-item .works-inner {\n  left: 50%;\n  position: absolute;\n  text-align: center;\n  top: 50%;\n  white-space: nowrap;\n  -webkit-transition: all 0.3s ease 0s;\n  -moz-transition: all 0.3s ease 0s;\n  -o-transition: all 0.3s ease 0s;\n  transition: all 0.3s ease 0s;\n  -webkit-transform: translate3d(0px, 0px, 0px) scale(0);\n  -moz-transform: translate3d(0px, 0px, 0px) scale(0);\n  -ms-transform: translate3d(0px, 0px, 0px) scale(0);\n  -o-transform: translate3d(0px, 0px, 0px) scale(0);\n  transform: translate3d(0px, 0px, 0px) scale(0);\n}\n.works-item h4 {\n  color: #c8a179;\n  font-weight: 700;\n  text-transform: uppercase;\n}\n.works-item p {\n  color: #f7f2e7;\n  font-size: 12px;\n  font-weight: 400;\n}\n.works-item:hover .overlay {\n  -webkit-transform: scale(1);\n  -moz-transform: scale(1);\n  -ms-transform: scale(1);\n  -o-transform: scale(1);\n  transform: scale(1);\n}\n.works-item:hover .works-inner {\n  -webkit-transform: translate(-50%, -50%) scale(1);\n  -moz-transform: translate(-50%, -50%) scale(1);\n  -ms-transform: translate(-50%, -50%) scale(1);\n  -o-transform: translate(-50%, -50%) scale(1);\n  transform: translate(-50%, -50%) scale(1);\n}\n\n.history-block {\n  background-color: #1b2e21;\n  position: relative;\n}\n.history-block .section-title h3::after {\n  background-color: #c8a179;\n}\n.history-block .section-title {\n  background-color: #1b2e21;\n  border-bottom: 1px solid #24402c;\n  left: 0;\n  margin-bottom: 0;\n  padding: 15px 34px 14px;\n  position: absolute;\n  right: 0;\n  top: 0;\n  z-index: 1;\n}\n\n.nicescroll-rails {\n  z-index: 2;\n}\n\n.nicescroll-rails-hr {\n  display: none !important;\n}\n\n.history-scroller {\n  padding-top: 82px;\n  max-height: 377px;\n}\n\n.history-item {\n  display: table;\n  font-family: \"Open