ild {\n    margin-left: auto;\n  }\n  .page-home .hexagon-item:nth-child(n+5) {\n    -webkit-transform: rotate(30deg) translate(0px, 0px);\n    -moz-transform: rotate(30deg) translate(0px, 0px);\n    -ms-transform: rotate(30deg) translate(0px, 0px);\n    -o-transform: rotate(30deg) translate(0px, 0px);\n    transform: rotate(30deg) translate(0px, 0px);\n  }\n  .author-image-large {\n    position: static;\n    margin-bottom: 50px;\n  }\n  .author-image-large img {\n    display: block;\n    height: auto;\n    margin: 0 auto;\n    width: 50%;\n  }\n  .about-author {\n    display: block;\n  }\n  .about-author .author-thumb {\n    border: 0 none;\n    margin-bottom: 15px;\n    margin-right: 0;\n    padding: 0;\n  }\n  .about-author .author-desc b {\n    display: block;\n  }\n  .about-author + p {\n    margin-bottom: 50px;\n  }\n  .progress {\n    display: block;\n  }\n  .progress .skill-name {\n    border-right: 0;\n    margin: 0 15px;\n    min-width: auto;\n    text-align: left;\n  }\n  .progress .skill-lavel {\n    border-left: 0;\n    margin: 0 15px;\n    min-width: auto;\n    text-align: left;\n  }\n  .service-hex {\n    float: none;\n    margin: 0 auto 40px;\n    width: 60%;\n  }\n  .service-hex:last-child {\n    margin-bottom: 0;\n  }\n  .service-hex:hover svg {\n    -webkit-transform: scale(1.8);\n    -moz-transform: scale(1.8);\n    -ms-transform: scale(1.8);\n    -o-transform: scale(1.8);\n    transform: scale(1.8);\n  }\n  .service-hex:hover .content {\n    width: 120%;\n  }\n  .history-block {\n    margin-bottom: 30px;\n  }\n  .contact-form .input-field.name {\n    margin-right: 0;\n  }\n  .page-nav {\n    bottom: auto;\n  }\n  .page-nav .flex {\n    display: block;\n    text-align: center;\n  }\n  .page-nav .flex span {\n    display: block;\n    margin: 20px 0;\n  }\n}\n.dark {\n  background-color: #132018;\n}\n.dark .page-home .overlay {\n  background-color: rgba(13, 23, 17, 0.97);\n}\n.dark .page-title h2 {\n  color: #f7f2e7;\n}\n.dark .page-title .title-bg {\n  color: rgba(143, 174, 122, 0.06);\n}\n.dark .section-title h3::before {\n  background-color: #f7f2e7;\n}\n.dark h1,\n.dark h2,\n.dark h3,\n.dark h4,\n.dark h5,\n.dark h6,\n.dark .about-author .author-desc p {\n  color: #f7f2e7;\n}\n.dark .switcher-body h4 {\n  color: #132018;\n}\n.dark .service-hex .st0 {\n  fill: transparent;\n}\n.dark .service-hex:hover .st0 {\n  fill: #f7f2e7;\n}\n.dark .testimonials .text,\n.dark .btn-border {\n  border-color: #1b2e21;\n}","//\r\n// Mixins\r\n//\r\n\r\n@import \"flex\";\r\n\r\n@mixin transition($transition) {\r\n   -webkit-transition: $transition;\r\n   -moz-transition: $transition;\r\n   -o-transition: $transition;\r\n   transition: $transition;\r\n}\r\n\r\n@mixin transform($transform) {\r\n   -webkit-transform: $transform;\r\n   -moz-transform: $transform;\r\n   -ms-transform: $transform;\r\n   -o-transform: $transform;\r\n   transform: $transform;\r\n}\r\n\r\n@mixin transform-origin($value) {\r\n   -webkit-transform-origin: $value;\r\n   -moz-transform-origin: $value;\r\n   -ms-transform-origin: $value;\r\n   -o-transform-origin: $value;\r\n   transform-origin: $value;\r\n}\r\n\r\n@mixin transition-delay($value) {\r\n   -webkit-transition-delay: $value;\r\n   -moz-transition-delay: $value;\r\n   -o-transition-delay: $value;\r\n   transition-delay: $value;\r\n}\r\n\r\n@mixin backface-visibility($value) {\r\n   -webkit-transform-origin: $value;\r\n   -moz-transform-origin: $value;\r\n   transform-origin: $value;\r\n}\r\n\r\n@mixin calc($property, $expression) {\r\n   #{$property}: -webkit-calc(#{$expression});\r\n   #{$property}: -moz-calc(#{$expression});\r\n   #{$property}: calc(#{$expression});\r\n}","// Flexbox Mixins\r\n// http://philipwalton.github.io/solved-by-flexbox/\r\n// https://github.com/philipwalton/solved-by-flexbox\r\n// \r\n// Copyright (c) 2013 Brian Franco\r\n//\r\n// Permission is hereby granted, free of charge, to any person obtaining a\r\n// copy of this software and associated documentation files (the\r\n// \"Software\"), to deal in the Software without restriction, including\r\n// without limitation the rights to use, copy, modify, merge, publish,\r\n// distribute, sublicense, and/or sell copies of the Software, and to\r\n// permit persons to whom the Software is furnished to do so, subject to\r\n// the following conditions:\r\n// The above copyright notice and this permission notice shall be included\r\n// in all copies or substantial portions of the Software.\r\n// THE SOFTWARE IS PROVIDED \"AS IS\", WITHOUT WARRANTY OF ANY KIND, EXPRESS\r\n// OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF\r\n// MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT.\r\n// IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY\r\n// CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT,\r\n// TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE\r\n// SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.\r\n//\r\n// This is a set of mixins for those who want to mess around with flexbox\r\n// using the native support of current browsers. For full support table\r\n// check: http://caniuse.com/flexbox\r\n//\r\n// Basically this will use:\r\n//\r\n// * Fallback, old syntax (IE10, mobile webkit browsers - no wrapping)\r\n// * Final standards syntax (FF, Safari, Chrome, IE11, Opera)\r\n//\r\n// This was inspired by:\r\n// \r\n// * http://dev.opera.com/articles/view/advanced-cross-browser-flexbox/\r\n// \r\n// With help from:\r\n// \r\n// * http://w3.org/tr/css3-flexbox/\r\n// * http://the-echoplex.net/flexyboxes/\r\n// * http://msdn.microsoft.com/en-us/library/ie/hh772069(v=vs.85).aspx\r\n// * http://css-tricks.com/using-flexbox/\r\n// * http://dev.opera.com/articles/view/advanced-cross-browser-flexbox/\r\n// * https://developer.mozilla.org/en-us/docs/web/guide/css/flexible_boxes\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Containers\r\n//\r\n// The 'flex' value causes an element to generate a block-level flex\r\n// container box.\r\n//\r\n// The 'inline-flex' value causes an element to generate a inline-level\r\n// flex container box. \r\n//\r\n// display: flex | inline-flex\r\n//\r\n// http://w3.org/tr/css3-flexbox/#flex-containers\r\n//\r\n// (Placeholder selectors for each type, for those who rather @extend)\r\n\r\n@mixin flexbox {\r\n\tdisplay: -webkit-box;\r\n\tdisplay: -webkit-flex;\r\n\tdisplay: -moz-flex;\r\n\tdisplay: -ms-flexbox;\r\n\tdisplay: flex;\r\n}\r\n\r\n%flexbox { @include flexbox; }\r\n\r\n//----------------------------------\r\n\r\n@mixin inline-flex {\r\n\tdisplay: -webkit-inline-box;\r\n\tdisplay: -webkit-inline-flex;\r\n\tdisplay: -moz-inline-flex;\r\n\tdisplay: -ms-inline-flexbox;\r\n\tdisplay: inline-flex;\r\n}\r\n\r\n%inline-flex { @include inline-flex; }\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Direction\r\n//\r\n// The 'flex-direction' property specifies how flex items are placed in\r\n// the flex container, by setting the direction of the flex container's\r\n// main axis. This determines the direction that flex items are laid out in. \r\n//\r\n// Values: row | row-reverse | column | column-reverse\r\n// Default: row\r\n//\r\n// http://w3.org/tr/css3-flexbox/#flex-direction-property\r\n\r\n@mixin flex-direction($value: row) {\r\n\t@if $value == row-reverse {\r\n\t\t-webkit-box-direction: reverse;\r\n\t\t-webkit-box-orient: horizontal;\r\n\t} @else if $value == column {\r\n\t\t-webkit-box-direction: normal;\r\n\t\t-webkit-box-orient: vertical;\r\n\t} @else if $value == column-reverse {\r\n\t\t-webkit-box-direction: reverse;\r\n\t\t-webkit-box-orient: vertical;\r\n\t} @else {\r\n\t\t-webkit-box-direction: normal;\r\n\t\t-webkit-box-orient: horizontal;\r\n\t}\r\n\t-webkit-flex-direction: $value;\r\n\t-moz-flex-direction: $value;\r\n\t-ms-flex-direction: $value;\r\n\tflex-direction: $value;\r\n}\r\n\t// Shorter version:\r\n\t@mixin flex-dir($args...) { @include flex-direction($args...); }\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Wrap\r\n//\r\n// The 'flex-wrap' property controls whether the flex container is single-line\r\n// or multi-line, and the direction of the cross-axis, which determines\r\n// the direction new lines are stacked in. \r\n//\r\n// Values: nowrap | wrap | wrap-reverse\r\n// Default: nowrap\r\n//\r\n// http://w3.org/tr/css3-flexbox/#flex-wrap-property\r\n\r\n@mixin flex-wrap($value: nowrap) {\r\n\t// No Webkit Box fallback.\r\n\t-webkit-flex-wrap: $value;\r\n\t-moz-flex-wrap: $value;\r\n\t@if $value == nowrap {\r\n\t\t-ms-flex-wrap: none;\r\n\t} @else { \r\n\t\t-ms-flex-wrap: $value; \r\n\t}\r\n\tflex-wrap: $value;\r\n}\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Flow (shorthand)\r\n//\r\n// The 'flex-flow' property is a shorthand for setting the 'flex-direction'\r\n// and 'flex-wrap' properties, which together define the flex container's\r\n// main and cross axes.\r\n//\r\n// Values: <flex-direction> | <flex-wrap> \r\n// Default: row nowrap\r\n//\r\n// http://w3.org/tr/css3-flexbox/#flex-flow-property\r\n\r\n@mixin flex-flow($values: (row nowrap)) {\r\n\t// No Webkit Box fallback.\r\n\t-webkit-flex-flow: $values;\r\n\t-moz-flex-flow: $values;\r\n\t-ms-flex-flow: $values;\r\n\tflex-flow: $values;\r\n}\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Order\r\n//\r\n// The 'order' property controls the order in which flex items appear within\r\n// their flex container, by assigning them to ordinal groups.\r\n//\r\n// Default: 0\r\n//\r\n// http://w3.org/tr/css3-flexbox/#order-property\r\n\r\n@mixin order($int: 0) {\r\n\t-webkit-box-ordinal-group: $int + 1;\r\n\t-webkit-order: $int;\r\n\t-moz-order: $int;\r\n\t-ms-flex-order: $int;\r\n\torder: $int;\r\n}\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Grow\r\n//\r\n// The 'flex-grow' property sets the flex grow factor. Negative numbers\r\n// are invalid.\r\n//\r\n// Default: 0\r\n//\r\n// http://w3.org/tr/css3-flexbox/#flex-grow-property\r\n\r\n@mixin flex-grow($int: 0) {\r\n\t-webkit-box-flex: $int;\r\n\t-webkit-flex-grow: $int;\r\n\t-moz-flex-grow: $int;\r\n\t-ms-flex-positive: $int;\r\n\tflex-grow: $int;\r\n}\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Shrink\r\n//\r\n// The 'flex-shrink' property sets the flex shrink factor. Negative numbers\r\n// are invalid.\r\n//\r\n// Default: 1\r\n//\r\n// http://w3.org/tr/css3-flexbox/#flex-shrink-property\r\n\r\n@mixin flex-shrink($int: 1) {\r\n\t-webkit-flex-shrink: $int;\r\n\t-moz-flex-shrink: $int;\r\n\t-ms-flex-negative: $int;\r\n\tflex-shrink: $int;\r\n}\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Basis\r\n//\r\n// The 'flex-basis' property sets the flex basis. Negative lengths are invalid. \r\n//\r\n// Values: Like \"width\" \r\n// Default: auto\r\n//\r\n// http://www.w3.org/TR/css3-flexbox/#flex-basis-property\r\n\r\n@mixin flex-basis($value: auto) {\r\n\t-webkit-flex-basis: $value;\r\n\t-moz-flex-basis: $value;\r\n\t-ms-flex-preferred-size: $value;\r\n\tflex-basis: $value;\r\n}\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox \"Flex\" (shorthand)\r\n//\r\n// The 'flex' property specifies the components of a flexible length: the\r\n// flex grow factor and flex shrink factor, and the flex basis. When an\r\n// element is a flex item, 'flex' is consulted instead of the main size\r\n// property to determine the main size of the element. If an element is\r\n// not a flex item, 'flex' has no effect.\r\n//\r\n// Values: none | <flex-grow> <flex-shrink> || <flex-basis>\r\n// Default: See individual properties (1 1 0).\r\n//\r\n// http://w3.org/tr/css3-flexbox/#flex-property\r\n\r\n@mixin flex($fg: 1, $fs: null, $fb: null) {\r\n    \r\n\t// Set a variable to be used by box-flex properties\r\n\t$fg-boxflex: $fg;\r\n\r\n\t// Box-Flex only supports a flex-grow value so let's grab the\r\n\t// first item in the list and just return that.\r\n\t@if type-of($fg) == 'list' {\r\n\t\t$fg-boxflex: nth($fg, 1);\r\n\t}\r\n\r\n\t-webkit-box-flex: $fg-boxflex;\r\n\t-webkit-flex: $fg $fs $fb;\r\n\t-moz-box-flex: $fg-boxflex;\r\n\t-moz-flex: $fg $fs $fb;\r\n\t-ms-flex: $fg $fs $fb;\r\n\tflex: $fg $fs $fb;\r\n}\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Justify Content\r\n//\r\n// The 'justify-content' property aligns flex items along the main axis\r\n// of the current line of the flex container. This is done after any flexible\r\n// lengths and any auto margins have been resolved. Typically it helps distribute\r\n// extra free space leftover when either all the flex items on a line are\r\n// inflexible, or are flexible but have reached their maximum size. It also\r\n// exerts some control over the alignment of items when they overflow the line.\r\n//\r\n// Note: 'space-*' values not supported in older syntaxes.\r\n//\r\n// Values: flex-start | flex-end | center | space-between | space-around\r\n// Default: flex-start\r\n//\r\n// http://w3.org/tr/css3-flexbox/#justify-content-property\r\n\r\n@mixin justify-content($value: flex-start) {\r\n\t@if $value == flex-start {\r\n\t\t-webkit-box-pack: start;\r\n\t\t-ms-flex-pack: start;\r\n\t} @else if $value == flex-end {\r\n\t\t-webkit-box-pack: end;\r\n\t\t-ms-flex-pack: end;\r\n\t} @else if $value == space-between {\r\n\t\t-webkit-box-pack: justify;\r\n\t\t-ms-flex-pack: justify;\r\n\t} @else if $value == space-around {\r\n\t\t-ms-flex-pack: distribute;\t\t\r\n\t} @else {\r\n\t\t-webkit-box-pack: $value;\r\n\t\t-ms-flex-pack: $value;\r\n\t}\r\n\t-webkit-justify-content: $value;\r\n\t-moz-justify-content: $value;\r\n\tjustify-content: $value;\r\n}\r\n\t// Shorter version:\r\n\t@mixin flex-just($args...) { @include justify-content($args...); }\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Align Items\r\n//\r\n// Flex items can be aligned in the cross axis of the current line of the\r\n// flex container, similar to 'justify-content' but in the perpendicular\r\n// direction. 'align-items' sets the default alignment for all of the flex\r\n// container's items, including anonymous flex items. 'align-self' allows\r\n// this default alignment to be overridden for individual flex items. (For\r\n// anonymous flex items, 'align-self' always matches the value of 'align-items'\r\n// on their associated flex container.) \r\n//\r\n// Values: flex-start | flex-end | center | baseline | stretch\r\n// Default: stretch\r\n//\r\n// http://w3.org/tr/css3-flexbox/#align-items-property\r\n\r\n@mixin align-items($value: stretch) {\r\n\t@if $value == flex-start {\r\n\t\t-webkit-box-align: start;\r\n\t\t-ms-flex-align: start;\r\n\t} @else if $value == flex-end {\r\n\t\t-webkit-box-align: end;\r\n\t\t-ms-flex-align: end;\r\n\t} @else {\r\n\t\t-webkit-box-align: $value;\r\n\t\t-ms-flex-align: $value;\r\n\t}\r\n\t-webkit-align-items: $value;\r\n\t-moz-align-items: $value;\r\n\talign-items: $value;\r\n}\r\n\r\n//----------------------------------\r\n\r\n// Flexbox Align Self\r\n//\r\n// Values: auto | flex-start | flex-end | center | baseline | stretch\r\n// Default: auto\r\n\r\n@mixin align-self($value: auto) {\r\n\t// No Webkit Box Fallback.\r\n\t-webkit-align-self: $value;\r\n\t-moz-align-self: $value;\r\n\t@if $value == flex-start {\r\n\t\t-ms-flex-item-align: start;\r\n\t} @else if $value == flex-end {\r\n\t\t-ms-flex-item-align: end;\r\n\t} @else {\r\n\t\t-ms-flex-item-align: $value;\r\n\t}\r\n\talign-self: $value;\r\n}\r\n\r\n//----------------------------------------------------------------------\r\n\r\n// Flexbox Align Content\r\n//\r\n// The 'align-content' property aligns a flex container's lines within the\r\n// flex container when there is extra space in the cross-axis, similar to\r\n// how 'justify-content' aligns individual items within the main-axis. Note,\r\n// this property has no effect when the flexbox has only a single line.\r\n//\r\n// Values: flex-start | flex-end | center | space-between | space-around | stretch\r\n// Default: stretch\r\n//\r\n// http://w3.org/tr/css3-flexbox/#align-content-property\r\n\r\n@mixin align-content($value: stretch) {\r\n\t// No Webkit Box Fallback.\r\n\t-webkit-align-content: $value;\r\n\t-moz-align-content: $value;\r\n\t@if $value == flex-start {\r\n\t\t-ms-flex-line-pack: start;\r\n\t} @else if $value == flex-end {\r\n\t\t-ms-flex-line-pack: end;\r\n\t} @else {\r\n\t\t-ms-flex-line-pack: $value;\r\n\t}\r\n\talign-content: $value;\r\n}","@import \"variables\";\n@import \"mixins\";\n@import \"base\";\n\n.preloader {\n  bottom: 0;\n  left: 0;\n  position: fixed;\n  right: 0;\n  top: 0;\n  z-index: 1000;\n  @include flexbox();\n  &.active.hidden {\n    display: none;\n  }\n}\n\n.loading-mask {\n  background-color: $primary-color;\n  height: 100%;\n  left: 0;\n  position: absolute;\n  top: 0;\n  width: 20%;\n  @include transition(all 0.6s cubic-bezier(0.61, 0, 0.6, 1) 0s);\n\n  &:nth-child(2) {\n    left: 20%;\n    @include transition-delay(0.1s);\n  }\n  &:nth-child(3) {\n    left: 40%;\n    @include transition-delay(0.2s);\n  }\n  &:nth-child(4) {\n    left: 60%;\n    @include transition-delay(0.3s);\n  }\n  &:nth-child(5) {\n    left: 80%;\n    @include transition-delay(0.4s);\n  }\n}\n\n.preloader.active {\n  &.done {\n    z-index: 0;\n  }\n  .loading-mask {\n    width: 0;\n  }\n}\n\n/*------------------------------------------------\n\tStart Styling\n-------------------------------------------------*/\n.site-wrapper {\n  border-top: 4px solid $primary-color;\n}\n\n.page-close {\n  font-size: 30px;\n  position: absolute;\n  right: 30px;\n  top: 30px;\n  z-index: 100;\n}\n\n.page-title {\n  margin-bottom: 75px;\n  img {\n    margin-bottom: 20px;\n  }\n  h2 {\n    font-size: 68px;\n    margin-bottom: 25px;\n    position: relative;\n    z-index: 0;\n    font-weight: 900;\n    text-transform: uppercase;\n  }\n  p {\n    font-size: 16px;\n  }\n  .title-bg {\n    color: rgba($light-dark, 0.07);\n    font-size: 158px;\n    left: 50%;\n    letter-spacing: 10px;\n    line-height: 0.7;\n    position: absolute;\n    top: 50%;\n    z-index: -1;\n    @include transform(translate(-50%, -50%));\n  }\n}\n\n.section-title {\n  margin-bottom: 20px;\n  overflow: hidden;\n  h3 {\n    display: inline-block;\n    position: relative;\n    &::before,\n    &::after {\n      content: \"\";\n      height: 2px;\n      position: absolute;\n      bottom: 8px;\n      @include calc(left, \"100% + 14px\");\n    }\n    &::before {\n      background-color: $light-dark;\n      width: 96px;\n      bottom: 14px;\n    }\n    &::after {\n      background-color: $primary-color;\n      width: 73px;\n    }\n  }\n  &.light {\n    h3 {\n      color: $light;\n      &::before {\n        background-color: $light;\n      }\n    }\n  }\n}\n\n.page-nav {\n  bottom: 40px;\n  left: 0;\n  position: absolute;\n  right: 0;\n  span {\n    font-family: $open-sans;\n    font-size: 14px;\n    font-weight: 500;\n    line-height: 1.3;\n    text-transform: uppercase;\n  }\n}\n\n//\n// Home\n//\n@import \"blocks/home\";\n@import \"blocks/welcome\";\n@import \"blocks/about\";\n@import \"blocks/games\";\n@import \"blocks/projects\";\n@import \"blocks/resume\";\n\n// about\n.progress {\n  background-color: $light-dark;\n  border-radius: 2px;\n  height: auto;\n  min-height: 45px;\n  @include align-items(center);\n  @include flexbox();\n  & > div {\n    color: $light;\n    font-family: $open-sans;\n    font-size: 12px;\n    letter-spacing: 1px;\n  }\n  .skill-name {\n    border-right: 2px solid $forest-500;\n    min-width: 160px;\n    text-align: center;\n    text-transform: uppercase;\n  }\n  .skill-bar {\n    background-color: $forest-900;\n    border-radius: 15px;\n    margin: 0 15px;\n    @include flex-grow(1);\n  }\n  .bar {\n    background-color: $tan; // the track behind it is forest\n    border-radius: 10px;\n    height: 8px;\n    width: 0;\n  }\n  .skill-lavel {\n    border-left: 2px solid $forest-500;\n    min-width: 70px;\n    text-align: center;\n    @include align-items(flex-end);\n    @include transition(all 0.3s ease 0s);\n  }\n}\n\n// Works\n\n.filter {\n  margin-bottom: 30px;\n  a {\n    border-bottom: 2px solid transparent;\n  }\n  .active {\n    color: $primary-color;\n    border-bottom-color: $primary-color;\n  }\n}\n\n.works-item {\n  font-family: $open-sans;\n  margin-bottom: 30px;\n  position: relative;\n\n  img {\n    width: 100%;\n  }\n\n  .overlay {\n    background-color: rgba($forest-700, 0.96);\n    position: absolute;\n    left: 0;\n    top: 0;\n    height: 100%;\n    width: 100%;\n    @include transition(all 0.3s ease 0s);\n    @include transform(scale(0));\n    &::before {\n      border: 1px solid $light;\n      bottom: 15px;\n      content: \"\";\n      left: 15px;\n      position: absolute;\n      right: 15px;\n      top: 15px;\n    }\n  }\n\n  .works-inner {\n    left: 50%;\n    position: absolute;\n    text-align: center;\n    top: 50%;\n    white-space: nowrap;\n    @include transition(all 0.3s ease 0s);\n    @include transform(translate3d(0px, 0px, 0px) scale(0));\n  }\n\n  h4 {\n    color: $tan; // sits on the dark hover overlay\n    font-weight: 700;\n    text-transform: uppercase;\n  }\n\n  p {\n    color: $light;\n    font-size: 12px;\n    font-weight: 400;\n  }\n\n  &:hover {\n    .overlay {\n      @include transform(scale(1));\n    }\n    .works-inner {\n      @include transform(translate(-50%, -50%) scale(1));\n    }\n  }\n}\n\n// history/ resume\n\n.history-block {\n  background-color: $light-dark;\n  position: relative;\n  // the accent rule under the heading is on forest here, not parchment\n  .section-title h3::after {\n    background-color: $tan;\n  }\n  .section-title {\n    background-color: $light-dark;\n    border-bottom: 1px solid $forest-600;\n    left: 0;\n    margin-bottom: 0;\n    padding: 15px 34px 14px;\n    position: absolute;\n    right: 0;\n    top: 0;\n    z-index: 1;\n  }\n}\n\n.nicescroll-rails {\n  z-index: 2;\n}\n\n// the history panel only scrolls vertically; the horizontal rail just draws a\n// stray line across the top of the page\n.nicescroll-rails-hr {\n  display: none !important;\n}\n\n.history-scroller {\n  padding-top: 82px;\n  max-height: 377px;\n}\n\n.history-item {\n  display: table;\n  font-family: $open-sans;\n  padding-left: 32px;\n  margin-bottom: 20px;\n  width: 100%;\n  & > * {\n    display: table-cell;\n    vertical-align: middle;\n  }\n  .history-icon {\n    padding-right: 25px;\n    position: relative;\n    width: 66px;\n    i {\n      font-size: 18px;\n      position: absolute;\n      top: 50%;\n      @include calc(left, \"50% - 12.5px\");\n      transform: translate(-50%, -50%);\n    }\n  }\n  h5 {\n    color: $light;\n    font-size: 16px;\n    font-weight: 600;\n    letter-spacing: 0.96px;\n    text-transform: uppercase;\n  }\n  span {\n    color: $tan-dim;\n    font-size: 12px;\n  }\n}\n\n.history-hex {\n  display: block;\n  position: relative;\n  width: 66px;\n  height: 38.11px;\n  background-color: $forest-600;\n  margin: 19.05px 0;\n  &::before,\n  &::after {\n    content: \"\";\n    position: absolute;\n    width: 0;\n    border-left: 33px solid transparent;\n    border-right: 33px solid transparent;\n  }\n  &::before {\n    bottom: 100%;\n    border-bottom: 19.05px solid $forest-600;\n  }\n  &::after {\n    top: 100%;\n    width: 0;\n    border-top: 19.05px solid $forest-600;\n  }\n}\n\n// Service hex\n//--------------------------------------\n.service-hex {\n  float: left;\n  position: relative;\n  width: 20%;\n  z-index: 1;\n  svg {\n    @include transform(scale(1.08));\n    @include transition(all 0.4s ease 0s);\n  }\n  .st0 {\n    stroke: $light-dark;\n    fill: $light;\n  }\n  .st1 {\n    fill: $light-dark;\n  }\n  .content {\n    color: $light;\n    left: 50%;\n    position: absolute;\n    text-align: center;\n    top: 50%;\n    width: 100%;\n    @include transform(translate(-50%, -50%));\n  }\n  .icon {\n    font-size: 30px;\n    margin-bottom: 9px;\n  }\n  h4 {\n    color: $light;\n    font-size: 16px;\n    margin-bottom: 20px;\n  }\n  p {\n    font-size: 14px;\n    height: 0;\n    line-height: 24px;\n    overflow: hidden;\n    @include transition(all 0.4s ease 0s);\n  }\n  &:hover {\n    z-index: 2;\n    svg {\n      @include transform(scale(1.5));\n    }\n    .st1 {\n      fill: $primary-color;\n    }\n    .content {\n      width: 135%;\n    }\n    p {\n      height: 72px;\n    }\n  }\n}\n\n// testimonials\n//--------------------------------------\n\n.testimonials {\n  .item {\n    padding-top: 33px;\n  }\n  .thumb {\n    float: left;\n    margin-top: -20px;\n    img {\n      width: auto;\n    }\n    @media only screen and (max-width: 991px) {\n      float: none;\n      margin-top: 0;\n      margin: auto;\n    }\n  }\n  .text {\n    border: 1px solid $parchment-line;\n    font-size: 14px;\n    font-style: italic;\n    line-height: 24px;\n    margin-left: 50px;\n    padding: 27px 30px 29px 142px;\n\n    @media only screen and (max-width: 991px) {\n      padding: 29px 30px 29px 30px;\n      margin-bottom: 20px;\n      text-align: center;\n    }\n  }\n  figcaption {\n    font-family: $open-sans;\n    font-size: 16px;\n    font-weight: 700;\n    padding-top: 15px;\n    text-align: center;\n  }\n  h4 {\n    font-family: $open-sans;\n    font-weight: 700;\n  }\n  span {\n    font-size: 12px;\n  }\n  .slick-slide {\n    margin: 0 15px;\n    &:focus {\n      outline: 0;\n    }\n    &:nth-child(2n) {\n      .thumb {\n        float: right;\n\n        @media only screen and (max-width: 991px) {\n          float: none;\n        }\n      }\n      .text {\n        margin-left: 0;\n        margin-right: 50px;\n        padding: 27px 142px 29px 30px;\n\n        @media only screen and (max-width: 991px) {\n          padding: 29px 30px 29px 30px;\n          margin-right: 0;\n        }\n      }\n    }\n  }\n  .slick-dots {\n    text-align: center;\n    button {\n      border: 2px solid $light-dark;\n      border-radius: 15px;\n      display: inline-block;\n      height: 11px;\n      margin: 0 4px;\n      width: 11px;\n      @include transition(all 0.3s ease 0s);\n\n      &:before {\n        display: none;\n      }\n    }\n    .slick-active button {\n      border-color: $primary-color;\n    }\n  }\n}\n\n.tm-hex {\n  position: relative;\n  width: 170px;\n  height: 98.15px;\n  margin: 49.07px 0;\n  background-size: auto 182.4427px;\n  background-position: center;\n  border-left: solid 6px $title-color;\n  border-right: solid 6px $title-color;\n\n  @media only screen and (max-width: 991px) {\n    margin: 49.07px auto;\n  }\n  &::after {\n    content: \"\";\n    position: absolute;\n    top: 3.4641px;\n    left: 0;\n    width: 158px;\n    height: 91.2213px;\n    z-index: 2;\n    background: inherit;\n  }\n  .hexTop,\n  .hexBottom {\n    position: absolute;\n    z-index: 1;\n    width: 120.21px;\n    height: 120.21px;\n    overflow: hidden;\n    background: inherit;\n    left: 18.9px;\n    @include transform(scaleY(0.5774) rotate(-45deg));\n    &::before,\n    &::after {\n      content: \"\";\n      position: absolute;\n      width: 158px;\n      height: 91.22134253196087px;\n      background: inherit;\n      @include transform-origin(0 0);\n      @include transform(rotate(45deg) scaleY(1.7321) translateY(-45.6107px));\n    }\n  }\n\n  .hexTop {\n    top: -60.1041px;\n    border-top: solid 8.4853px $title-color;\n    border-right: solid 8.4853px $title-color;\n    &::after {\n      background-position: center top;\n    }\n  }\n\n  .hexBottom {\n    bottom: -60.1041px;\n    border-bottom: solid 8.4853px $title-color;\n    border-left: solid 8.4853px $title-color;\n    &::after {\n      background-position: center bottom;\n    }\n  }\n}\n\n// contact\n\n.contact-block {\n  margin-bottom: 30px;\n  &:last-child {\n    margin-bottom: 0;\n  }\n  .media-left {\n    font-size: 40px;\n    max-width: 50px;\n    min-width: 50px;\n    padding-right: 0;\n    text-align: center;\n  }\n  .media-body {\n    padding-left: 30px;\n  }\n  h4 {\n    font-size: 18px;\n    text-transform: uppercase;\n    font-weight: 600;\n  }\n  p {\n    font-weight: 400;\n    font-size: 15px;\n  }\n}\n\n.contact-social {\n  list-style: outside none none;\n  margin: 0;\n  padding: 0;\n  li {\n    display: inline-block;\n    position: relative;\n    width: 43px;\n    a {\n      color: $light;\n      display: block;\n      font-size: 14px;\n      height: 50px;\n      left: 50%;\n      line-height: 50px;\n      position: absolute;\n      text-align: center;\n      top: 50%;\n      width: 43px;\n      @include transform(translate(-50%, -50%));\n    }\n    &:hover {\n      span {\n        background-color: $primary-color;\n        &::before {\n          border-bottom-color: $primary-color;\n        }\n        &::after {\n          border-top-color: $primary-color;\n        }\n      }\n    }\n  }\n}\n\n.contact-social-hex {\n  display: block;\n  position: relative;\n  width: 43px;\n  height: 24.83px;\n  background-color: $forest-700;\n  margin: 12.41px 0;\n  @include transition(all 0.3s ease 0s);\n  &::before,\n  &::after {\n    content: \"\";\n    position: absolute;\n    width: 0;\n    border-left: 21.5px solid transparent;\n    border-right: 21.5px solid transparent;\n    @include transition(all 0.3s ease 0s);\n  }\n  &::before {\n    bottom: 100%;\n    border-bottom: 12.41px solid $forest-700;\n  }\n  &::after {\n    top: 100%;\n    width: 0;\n    border-top: 12.41px solid $forest-700;\n  }\n  &:hover {\n    &::after {\n      border-bottom-color: $primary-color;\n    }\n    &::before {\n      border-top-color: $primary-color;\n    }\n  }\n}\n\n.contact-form {\n  .input-field {\n    margin-bottom: 10px;\n    &.name {\n      margin-right: 5px;\n    }\n    &.email {\n      margin-left: 5px;\n    }\n    label.error {\n      color: #b4432f;\n      font-size: 13px;\n      margin: 0;\n    }\n  }\n\n  .input-icon {\n    background-color: $light-dark;\n    border-radius: 3px 0 0 3px;\n    border-right: 1px solid rgba($light, 0.2);\n    line-height: 48px;\n    min-width: 53px;\n    text-align: center;\n    left: 0;\n    line-height: 48px;\n    min-width: 53px;\n    position: absolute;\n    top: 0;\n  }\n\n  .form-control {\n    background-color: $light-dark;\n    color: $parchment-dim;\n    border: 0 none;\n    border-radius: 3px;\n    height: 48px;\n    padding-left: 70px;\n    width: 100%;\n    font-family: $open-sans;\n    &:focus {\n      box-shadow: none;\n      color: $light;\n    }\n  }\n\n  textarea.form-control {\n    border-radius: 3px;\n    height: 120px;\n    padding: 15px 10px 15px 70px;\n  }\n\n  .message {\n    .input-icon {\n      position: absolute;\n      left: 0;\n      top: 0;\n    }\n  }\n}\n\n.msg-success,\n.msg-failed {\n  display: none;\n  margin-top: 15px;\n}\n\n.msg-success {\n  color: $primary-color;\n}\n\n.pt-table.desktop-768 .pt-tablecell {\n  padding-bottom: 110px;\n  padding-top: 60px;\n  .page-nav {\n    bottom: 40px;\n  }\n}\n\n/* =================================== */\n/*  Color Switcher\n/* =================================== */\n.preview-wrapper {\n  background-color: #fff;\n  border: 1px solid #ddd;\n  border-right: 0;\n  color: #333;\n  height: 150px;\n  right: 0px;\n  position: fixed;\n  top: 100px;\n  width: 260px;\n  z-index: 1200;\n  -webkit-transition: all 0.4s ease-in-out 0s;\n  -moz-transition: all 0.4s ease-in-out 0s;\n  -o-transition: all 0.4s ease-in-out 0s;\n  transition: all 0.4s ease-in-out 0s;\n  transform: translateX(100%);\n}\n.preview-wrapper.extend {\n  -webkit-transform: translateX(0px);\n  -moz-transform: translateX(0px);\n  -ms-transform: translateX(0px);\n  -o-transform: translateX(0px);\n  transform: translateX(0px);\n}\n.switcher-head {\n  color: #333;\n  font-size: 18px;\n  font-weight: 600;\n  height: 46px;\n  line-height: 46px;\n  position: relative;\n}\n.switcher-head span {\n  border-bottom: 2px solid #eeeeee;\n  display: block;\n  margin: 0 20px;\n}\n.switcher-trigger {\n  background-color: #fff;\n  border: 1px solid #ddd;\n  border-right: 0;\n  cursor: pointer;\n  font-size: 20px;\n  height: 48px;\n  left: -48px;\n  line-height: 46px;\n  position: absolute;\n  text-align: center;\n  top: -1px;\n  width: 48px;\n}\n.switcher-body {\n  background-color: #fff;\n  height: -webkit-calc(100% - 50px);\n  height: calc(100% - 50px);\n  left: 0;\n  padding: 20px;\n  position: fixed;\n  right: 0;\n  top: 47px;\n  outline: none;\n}\n.switcher-body h4 {\n  font-size: 16px;\n  margin-bottom: 10px;\n}\n.switcher-body select {\n  border: 1px solid #e5e5e5;\n  height: 40px;\n  margin-bottom: 20px;\n  width: 100%;\n  -webklit--appearance: none;\n  -moz-appearance: none;\n  appearance: none;\n}\n.color-options {\n  margin-bottom: 10px;\n  padding: 0;\n}\n.color-options li {\n  display: inline-block;\n  background-color: #e6ae03;\n  height: 30px;\n  margin-bottom: 10px;\n  margin-right: 6px;\n  text-indent: -9999em;\n  width: 30px;\n  cursor: pointer;\n}\n.color-options li.c0 {\n  background-color: #fa6862;\n}\n.color-options li.c1 {\n  background-color: #02b7ce;\n}\n.color-options li.c2 {\n  background-color: #86a438;\n}\n.color-options li.c3 {\n  background-color: #f3a36d;\n}\n.pattern-options li {\n  font-family: \"Roboto\", sans-serif;\n  border: 1px solid #cccccc;\n  cursor: pointer;\n  float: left;\n  height: 40px;\n  margin: 0 10px 10px 0;\n  text-transform: capitalize;\n  width: 50px;\n}\n.pattern-options li:last-child {\n  border: 0 none;\n  height: auto;\n  padding-top: 8px;\n  width: auto;\n}\n.pattern-options li img {\n  width: 100%;\n  height: 100%;\n}\n\n/*------------------------------------------------\n\tResponsive Media Queries\n-------------------------------------------------*/\n@import \"media-queries\";\n@import \"dark\";\n","/*------------------------------------------------\n    Home Page\n-------------------------------------------------*/\n.page-home {\n  background-position: center center;\n  background-repeat: no-repeat;\n  background-size: cover;\n  vertical-align: middle;\n  .overlay {\n    background-color: rgba($light, 0.93);\n  }\n}\n\n/* End of container */\n\n// Contains 2 hexagons (.hex)\n.hexagon-item {\n  cursor: pointer;\n  width: $hexWidth;\n  height: $hexHeight;\n  float: left;\n  margin-left: -29px;\n  z-index: 0;\n  position: relative;\n  @include transform(rotate(30deg));\n  &:first-child {\n    margin-left: 0;\n  }\n  // Hover state\n  &:hover {\n    z-index: 1;\n    .hex-item:last-child {\n      opacity: 1;\n      @include transform(scale(1.3));\n    }\n    .hex-item:first-child {\n      opacity: 1;\n      @include transform(scale(1.2));\n      div:before,\n      div:after {\n        height: $borderHover;\n      }\n    }\n    .hex-item {\n      div::before,\n      div::after {\n        background-color: $primary-color;\n      }\n    }\n    .hex-content svg {\n      @include transform(scale(0.97));\n    }\n  }\n}\n\n// The menu wraps at four hexagons per row, so everything from the fifth\n// onwards is the second row and gets nudged into the first row's valleys.\n.page-home {\n  .hexagon-item:nth-child(n + 5) {\n    @include transform(rotate(30deg) translate(87px, -80px));\n  }\n}\n\n// Contains 3 div that makes the hexagon\n.hex-item {\n  position: absolute;\n  top: 0;\n  left: calc($edgeSize/2);\n  width: $edgeSize;\n  height: $hexHeight;\n  // Inset\n  &:first-child {\n    z-index: 0;\n    @include transform(scale(0.9));\n    @include transition(all 0.3s $ease-out-quart);\n  }\n  // Outset\n  &:last-child {\n    transition: all 0.3s $ease-out-expo;\n    z-index: 1;\n  }\n  div {\n    box-sizing: border-box;\n    position: absolute;\n    top: 0;\n    width: $edgeSize;\n    height: $hexHeight;\n    @include transform-origin(center center);\n    &::before,\n    &::after {\n      background-color: $light-dark;\n      content: \"\";\n      position: absolute;\n      width: 100%;\n      height: 3px;\n      @include transition(all 0.3s $ease-out-quart 0s);\n    }\n    &:before {\n      top: 0;\n    }\n    &:after {\n      bottom: 0;\n    }\n    &:nth-child(1) {\n      @include transform(rotate(0deg));\n    }\n    &:nth-child(2) {\n      @include transform(rotate(60deg));\n    }\n    &:nth-child(3) {\n      @include transform(rotate(120deg));\n    }\n  }\n}\n\n.hex-content {\n  color: $light;\n  display: block;\n  height: 180px;\n  margin: 0 auto;\n  position: relative;\n  text-align: center;\n  transform: rotate(-30deg);\n  width: 156px;\n  .hex-content-inner {\n    left: 50%;\n    margin: -3px 0 0 2px;\n    position: absolute;\n    top: 50%;\n    @include transform(translate(-50%, -50%));\n  }\n  .icon {\n    display: block;\n    font-size: 36px;\n    line-height: 30px;\n    margin-bottom: 11px;\n  }\n  .title {\n    display: block;\n    font-family: $open-sans;\n    font-size: 14px;\n    letter-spacing: 1px;\n    line-height: 24px;\n    text-transform: uppercase;\n  }\n  svg {\n    left: -7px;\n    position: absolute;\n    top: -13px;\n    transform: scale(0.87);\n    z-index: -1;\n    @include transition(all 0.3s $ease-out-quart 0s);\n  }\n  &:hover {\n    color: $light;\n  }\n}\n","\n/*------------------------------------------------\n    Welcome Page\n-------------------------------------------------*/\n\n.author-image-large {\n    position: absolute;\n    right: 0;\n    top: 0;\n    img {\n        @include calc(height, \"100vh - 4px\");\n    }\n}\n\n// .hexagon-item {\n// \ta {\n// \t\tpath {\n// \t\t\tfill: #59C4B4;\n// \t\t}\n// \t}\n// }","\n/*------------------------------------------------\n    About Page\n-------------------------------------------------*/\n.about-author {\n\tmargin-bottom: 23px;\n\t@include align-items(center);\n\t@include flexbox();\n\t.author-thumb {\n\t  \tbackground-color: $light;\n\t  \tborder: 5px solid $light-dark;\n\t  \tmargin-right: 30px;\n\t  \tpadding: 5px;\n\t  \timg {\n\t  \t\tborder: 2px solid $light-dark;\n\t  \t\twidth: 145px;\n\t  \t}\n\t}\n\t.author-desc {\n\t\tp {\n\t\t\tcolor: $light-dark;\n\t\t\tfont-family: $open-sans;\n\t\t\tletter-spacing: 1px;\n\t\t\tmargin-bottom: 4px;\n\t\t\ttext-transform: uppercase;\n\t\t}\n\t\tb {\n\t\t\tfont-family: $open-sans;\n\t\t}\n\t}\n}","/*------------------------------------------------\n    Games Page\n-------------------------------------------------*/\n.page-games {\n  .page-title {\n    margin-bottom: 22px;\n  }\n}\n\n// View switch (All / Daily)\n.games-view {\n  display: inline-block;\n  list-style: none;\n  margin: 0 0 12px;\n  padding: 0;\n  li {\n    display: inline-block;\n    margin: 0 12px;\n  }\n  a {\n    border-bottom: 2px solid transparent;\n    display: inline-block;\n    font-family: $open-sans;\n    font-size: 14px;\n    letter-spacing: 1px;\n    padding-bottom: 2px;\n    text-transform: uppercase;\n  }\n  .active {\n    border-bottom-color: $primary-color;\n    color: $primary-color;\n  }\n}\n\n.games-note {\n  font-family: $open-sans;\n  font-size: 12px;\n  letter-spacing: 1px;\n  margin-bottom: 30px;\n  min-height: 22px;\n  text-transform: uppercase;\n  b {\n    color: $title-color;\n    font-weight: 600;\n  }\n}\n\n.games-empty {\n  font-family: $open-sans;\n  font-size: 14px;\n  margin-bottom: 40px;\n}\n\n// Flex row so every card in a row is the same height whatever the tagline\n// length, and so a part-full last row stays centred.\n.games-grid {\n  @include flexbox();\n  @include flex-wrap(wrap);\n  @include justify-content(center);\n  // bootstrap's clearfix pseudo elements would become flex items here\n  &::before,\n  &::after {\n    display: none;\n  }\n  & > div {\n    margin-bottom: 30px;\n    @include flexbox();\n  }\n}\n\n// Game card\n.game-item {\n  background-color: $light-dark;\n  font-family: $open-sans;\n  padding: 28px 20px 26px;\n  position: relative;\n  text-align: center;\n  width: 100%;\n  @include flexbox();\n  @include flex-direction(column);\n  @include transition(all 0.3s ease 0s);\n\n  // decorative only - without this it sits over the play button and eats clicks\n  &::before {\n    border: 1px solid rgba($light, 0.08);\n    bottom: 12px;\n    content: \"\";\n    left: 12px;\n    pointer-events: none;\n    position: absolute;\n    right: 12px;\n    top: 12px;\n    @include transition(all 0.3s ease 0s);\n  }\n\n  h4 {\n    // card sits on forest, so the accent steps up a weight to stay readable\n    color: $tan;\n    font-size: 16px;\n    font-weight: 700;\n    letter-spacing: 0.96px;\n    margin-bottom: 12px;\n    text-transform: uppercase;\n  }\n\n  // grows to fill the tallest card in the row, keeping the badges and\n  // the button on a common baseline across the row\n  .game-tagline {\n    color: $tan-dim;\n    font-size: 13px;\n    line-height: 22px;\n    margin-bottom: 15px;\n    @include flex-grow(1);\n  }\n\n  &:hover {\n    &::before {\n      bottom: 8px;\n      left: 8px;\n      right: 8px;\n      top: 8px;\n    }\n    .game-hex {\n      background-color: $primary-color;\n      &::before {\n        border-bottom-color: $primary-color;\n      }\n      &::after {\n        border-top-color: $primary-color;\n      }\n    }\n  }\n}\n\n// Hexagon icon holder, same construction as the contact/history hexes\n.game-hex {\n  background-color: $forest-600;\n  display: block;\n  height: 32.33px;\n  margin: 16.16px auto 24px;\n  position: relative;\n  width: 56px;\n  @include transition(all 0.3s ease 0s);\n  // left is explicit because the card centres its text, which would\n  // otherwise shift the static position of these two triangles.\n  &::before,\n  &::after {\n    border-left: 28px solid transparent;\n    border-right: 28px solid transparent;\n    content: \"\";\n    left: 0;\n    position: absolute;\n    width: 0;\n    @include transition(all 0.3s ease 0s);\n  }\n  &::before {\n    border-bottom: 16.16px solid $forest-600;\n    bottom: 100%;\n  }\n  &::after {\n    border-top: 16.16px solid $forest-600;\n    top: 100%;\n  }\n  i {\n    color: $light;\n    font-size: 24px;\n    left: 50%;\n    position: absolute;\n    top: 50%;\n    z-index: 1;\n    @include transform(translate(-50%, -50%));\n  }\n}\n\n// Fixed line-height so a card with no badges is exactly as tall as one with.\n.game-meta {\n  line-height: 20px;\n  min-height: 22px;\n}\n\n.game-badge {\n  border-radius: 2px;\n  color: $parchment-dim;\n  display: inline-block;\n  font-size: 10px;\n  letter-spacing: 1px;\n  line-height: 20px;\n  margin: 0 1px;\n  padding: 0 8px;\n  text-transform: uppercase;\n  vertical-align: top;\n  background-color: $forest-600;\n  &.daily {\n    background-color: $primary-color;\n    color: $light;\n  }\n  &.soon {\n    background-color: transparent;\n    border: 1px solid $forest-500;\n    color: $sage;\n    line-height: 18px;\n  }\n  &.played {\n    background-color: transparent;\n    border: 1px solid $sage;\n    color: $tan;\n    line-height: 18px;\n  }\n}\n\n.game-play {\n  border: 1px solid rgba($light, 0.25);\n  color: $light;\n  display: inline-block;\n  font-size: 12px;\n  font-weight: 600;\n  letter-spacing: 1px;\n  line-height: 34px;\n  margin-top: 18px;\n  padding: 0 26px;\n  text-transform: uppercase;\n  @include align-self(center);\n  &:hover,\n  &:focus {\n    background-color: $primary-color;\n    border-color: $primary-color;\n    color: $light;\n  }\n  &.disabled {\n    border-style: dashed;\n    color: $sage;\n    cursor: default;\n    pointer-events: none;\n  }\n}\n","/*------------------------------------------------\n    Projects Page\n-------------------------------------------------*/\n.page-works {\n  .page-title {\n    margin-bottom: 30px;\n  }\n}\n\n// Category filter row (isotope, wired up in script.js)\n.projects-filter {\n  list-style: none;\n  margin: 0 0 40px;\n  padding: 0;\n  li {\n    display: inline-block;\n    margin: 0 12px 6px;\n  }\n  a {\n    border-bottom: 2px solid transparent;\n    display: inline-block;\n    font-family: $open-sans;\n    font-size: 13px;\n    letter-spacing: 1px;\n    padding-bottom: 2px;\n    text-transform: uppercase;\n  }\n  .active {\n    border-bottom-color: $primary-color;\n    color: $primary-color;\n  }\n}\n\n// Project card: square tile on top, always-visible details underneath\n.project-item {\n  background-color: $light-dark;\n  font-family: $open-sans;\n  margin-bottom: 30px;\n  overflow: hidden;\n  position: relative;\n  text-align: left;\n  @include transition(all 0.3s ease 0s);\n\n  // Fixed-height tile. Without it the thumbnail height follows the source\n  // image's aspect ratio, so the square logos rendered as huge blocks - and at\n  // col-xs-12 they grew with the viewport. Art is contained, never cropped,\n  // because these are logos rather than screenshots.\n  .project-thumb {\n    align-items: center;\n    background-color: $forest-600;\n    display: flex;\n    height: 190px;\n    justify-content: center;\n    margin: 0;\n    overflow: hidden;\n    position: relative;\n    img {\n      display: block;\n      max-height: 100%;\n      max-width: 100%;\n      object-fit: contain;\n      @include transition(all 0.45s ease 0s);\n    }\n    @media only screen and (max-width: 767px) {\n      height: 160px;\n    }\n  }\n  &:hover .project-thumb img {\n    @include transform(scale(1.05));\n  }\n\n  .project-body {\n    padding: 20px 22px 24px;\n  }\n\n  h4 {\n    color: $light;\n    font-size: 15px;\n    font-weight: 700;\n    letter-spacing: 0.9px;\n    margin-bottom: 3px;\n    text-transform: uppercase;\n    a {\n      color: inherit;\n      &:hover,\n      &:focus {\n        color: $tan;\n      }\n    }\n  }\n\n  .project-cat {\n    // on the forest card, so the lighter weight of the accent\n    color: $tan;\n    display: block;\n    font-size: 11px;\n    letter-spacing: 1.2px;\n    margin-bottom: 12px;\n    text-transform: uppercase;\n  }\n\n  .project-desc {\n    color: $tan-dim;\n    font-size: 13px;\n    line-height: 22px;\n    margin-bottom: 14px;\n  }\n\n  .project-tags {\n    margin-bottom: 4px;\n  }\n\n  .project-links {\n    margin-top: 12px;\n    a {\n      border: 1px solid rgba($light, 0.25);\n      color: $light;\n      display: inline-block;\n      font-size: 11px;\n      font-weight: 600;\n      letter-spacing: 1px;\n      line-height: 30px;\n      margin: 0 6px 6px 0;\n      padding: 0 16px;\n      text-transform: uppercase;\n      &:hover,\n      &:focus {\n        background-color: $primary-color;\n        border-color: $primary-color;\n        color: $light;\n      }\n    }\n  }\n}\n\n// Small uppercase chip, shared by project cards and the resume skills block\n.tag-chip {\n  background-color: $forest-600;\n  border-radius: 2px;\n  color: $parchment-dim;\n  display: inline-block;\n  font-size: 10px;\n  letter-spacing: 1px;\n  line-height: 20px;\n  margin: 0 4px 6px 0;\n  padding: 0 9px;\n  text-transform: uppercase;\n  vertical-align: top;\n}\n","/*------------------------------------------------\n    Resume Page\n-------------------------------------------------*/\n.page-resume {\n  .page-title {\n    margin-bottom: 45px;\n    p a {\n      border-bottom: 1px dotted rgba($light-dark, 0.4);\n      &:hover {\n        border-bottom-color: $primary-color;\n        color: $primary-color;\n      }\n    }\n  }\n\n  .history-item {\n    padding-right: 28px;\n  }\n\n  .history-text {\n    ul {\n      color: $tan-dim;\n      font-size: 13px;\n      line-height: 22px;\n      margin: 8px 0 0;\n      padding-left: 18px;\n      li {\n        margin-bottom: 6px;\n      }\n    }\n  }\n}\n\n// Skills band under the two history columns\n.resume-skills {\n  background-color: $light-dark;\n  font-family: $open-sans;\n  margin-top: 30px;\n  padding: 24px 34px 20px;\n\n  .section-title {\n    margin-bottom: 18px;\n  }\n\n  .skills-group {\n    margin-bottom: 10px;\n    h5 {\n      color: $light;\n      display: inline-block;\n      font-size: 12px;\n      letter-spacing: 1px;\n      margin: 0 16px 6px 0;\n      min-width: 120px;\n      text-transform: uppercase;\n      vertical-align: top;\n    }\n    .skills-chips {\n      display: inline-block;\n      max-width: calc(100% - 150px);\n      vertical-align: top;\n      @media only screen and (max-width: 767px) {\n        display: block;\n        max-width: none;\n      }\n    }\n  }\n}\n\n// \"More of me\" links under the resume (projects / proofs / publications)\n.resume-more {\n  margin-top: 30px;\n  text-align: center;\n  span {\n    color: $sage;\n    display: inline-block;\n    font-family: $open-sans;\n    font-size: 11px;\n    letter-spacing: 1.5px;\n    margin-right: 14px;\n    text-transform: uppercase;\n  }\n  a {\n    border: 1px solid rgba($light-dark, 0.25);\n    color: $title-color;\n    display: inline-block;\n    font-family: $open-sans;\n    font-size: 11px;\n    font-weight: 600;\n    letter-spacing: 1px;\n    line-height: 32px;\n    margin: 0 5px 8px;\n    padding: 0 20px;\n    text-transform: uppercase;\n    &:hover,\n    &:focus {\n      background-color: $primary-color;\n      border-color: $primary-color;\n      color: $light;\n    }\n  }\n}\n","/*============================================================\r\n\tMacbook pro 13 inch\r\n==============================================================*/\r\n@media only screen and (min-width: 1151px) and (max-width: 1366px) {}\r\n\r\n\r\n/*============================================================\r\n\tFor Small Desktop / tablet landscape\r\n==============================================================*/\r\n\r\n@media (min-width: 980px) and (max-width: 1150px) {\r\n\r\n\r\n\t.author-image-large {\r\n\t\timg {\r\n\t\t\t@include calc(height, \"80vh - 4px\");\r\n\t\t}\r\n\t}\r\n}\r\n\r\n\r\n/*============================================================\r\n\tTablet (Portrait) Design for a width of 768px\r\n==============================================================*/\r\n\r\n@media (min-width: 768px) and (max-width: 979px) {\r\n\tbody {\r\n\t\toverflow-x: hidden;\r\n\t}\r\n\r\n\t.page-title {\r\n\t\th2 {\r\n\t\t\tfont-size: 40px;\r\n\t\t}\r\n\r\n\t\t.title-bg {\r\n\t\t\tfont-size: 100px;\r\n\t\t}\r\n\t}\r\n\r\n\t.author-image-large {\r\n\t\tposition: static;\r\n\t\tmargin-bottom: 50px;\r\n\r\n\t\timg {\r\n\t\t\tdisplay: block;\r\n\t\t\theight: auto;\r\n\t\t\tmargin: 0 auto;\r\n\t\t\twidth: 50%;\r\n\t\t}\r\n\t}\r\n\r\n\t.about-author {\r\n\t\t+p {\r\n\t\t\tmargin-bottom: 50px;\r\n\t\t}\r\n\t}\r\n\r\n\t.service-hex {\r\n\t\twidth: 33.3333%;\r\n\r\n\t\t&:hover {\r\n\t\t\tz-index: 2;\r\n\r\n\t\t\tsvg {\r\n\t\t\t\t@include transform(scale(1.5));\r\n\t\t\t}\r\n\r\n\t\t\t.content {\r\n\t\t\t\twidth: 105%;\r\n\t\t\t}\r\n\t\t}\r\n\r\n\t\t&:nth-child(4),\r\n\t\t&:nth-child(5) {\r\n\t\t\t@include transform(translate(50%, -15%));\r\n\t\t}\r\n\t}\r\n\r\n\t.testimonials {\r\n\t\t.item {\r\n\t\t\tpadding-top: 45px;\r\n\t\t}\r\n\r\n\t\t.thumb {\r\n\t\t\tmargin-top: -45px;\r\n\t\t}\r\n\t}\r\n\r\n\t.history-item .history-text {\r\n\t\tpadding-right: 15px;\r\n\t}\r\n\r\n\t.page-nav {\r\n\t\tbottom: auto;\r\n\r\n\t\t.flex {\r\n\t\t\tdisplay: block;\r\n\t\t\ttext-align: center;\r\n\r\n\t\t\tspan {\r\n\t\t\t\tdisplay: block;\r\n\t\t\t\tmargin: 20px 0;\r\n\t\t\t}\r\n\t\t}\r\n\t}\r\n}\r\n\r\n\r\n/*============================================================\r\n\tMobile (Portrait) Design for a width of 320px\r\n==============================================================*/\r\n\r\n@media only screen and (max-width: 767px) {\r\n\r\n\tbody {\r\n\t\toverflow-x: hidden;\r\n\t}\r\n\r\n\t.pt-table {\r\n\t\theight: auto;\r\n\t}\r\n\r\n\t.pt-table,\r\n\t.pt-tablecell {\r\n\t\tdisplay: block;\r\n\t}\r\n\r\n\t.page-title {\r\n\t\tmargin-bottom: 45px;\r\n\r\n\t\th2 {\r\n\t\t\tfont-size: 35px;\r\n\t\t}\r\n\r\n\t\t.title-bg {\r\n\t\t\tfont-size: 50px;\r\n\t\t}\r\n\t}\r\n\r\n\t.hexagon-item {\r\n\t\tfloat: none;\r\n\t\tmargin: 0 auto 50px;\r\n\r\n\t\t&:first-child {\r\n\t\t\tmargin-left: auto;\r\n\t\t}\r\n\t}\r\n\r\n\t.page-home {\r\n\r\n\t\t.hexagon-item:nth-child(n + 5) {\r\n\t\t\t@include transform (rotate(30deg) translate(0px, 0px));\r\n\t\t}\r\n\t}\r\n\r\n\t.author-image-large {\r\n\t\tposition: static;\r\n\t\tmargin-bottom: 50px;\r\n\r\n\t\timg {\r\n\t\t\tdisplay: block;\r\n\t\t\theight: auto;\r\n\t\t\tmargin: 0 auto;\r\n\t\t\twidth: 50%;\r\n\t\t}\r\n\t}\r\n\r\n\t.about-author {\r\n\t\tdisplay: block;\r\n\r\n\t\t.author-thumb {\r\n\t\t\tborder: 0 none;\r\n\t\t\tmargin-bottom: 15px;\r\n\t\t\tmargin-right: 0;\r\n\t\t\tpadding: 0;\r\n\t\t}\r\n\r\n\t\t.author-desc b {\r\n\t\t\tdisplay: block;\r\n\t\t}\r\n\r\n\t\t+p {\r\n\t\t\tmargin-bottom: 50px;\r\n\t\t}\r\n\t}\r\n\r\n\t.progress {\r\n\t\tdisplay: block;\r\n\r\n\t\t.skill-name {\r\n\t\t\tborder-right: 0;\r\n\t\t\tmargin: 0 15px;\r\n\t\t\tmin-width: auto;\r\n\t\t\ttext-align: left;\r\n\t\t}\r\n\r\n\t\t.skill-lavel {\r\n\t\t\tborder-left: 0;\r\n\t\t\tmargin: 0 15px;\r\n\t\t\tmin-width: auto;\r\n\t\t\ttext-align: left;\r\n\t\t}\r\n\t}\r\n\r\n\t.service-hex {\r\n\t\tfloat: none;\r\n\t\tmargin: 0 auto 40px;\r\n\t\twidth: 60%;\r\n\r\n\t\t&:last-child {\r\n\t\t\tmargin-bottom: 0;\r\n\t\t}\r\n\r\n\t\t&:hover {\r\n\t\t\tsvg {\r\n\t\t\t\t@include transform(scale(1.8));\r\n\t\t\t}\r\n\r\n\t\t\t.content {\r\n\t\t\t\twidth: 120%;\r\n\t\t\t}\r\n\t\t}\r\n\t}\r\n\r\n\t.history-block {\r\n\t\tmargin-bottom: 30px;\r\n\t}\r\n\r\n\t.contact-form .input-field.name {\r\n\t\tmargin-right: 0;\r\n\t}\r\n\r\n\t.page-nav {\r\n\t\tbottom: auto;\r\n\t\t.flex {\r\n\t\t\tdisplay: block;\r\n\t\t\ttext-align: center;\r\n\t\t\tspan {\r\n\t\t\t\tdisplay: block;\r\n\t\t\t\tmargin: 20px 0;\r\n\t\t\t}\r\n\t\t}\r\n\t}\r\n\r\n}\r\n","// compiled standalone as well as appended to style.scss, so it needs the palette\n@import \"variables\";\n\n.dark {\n\tbackground-color: $forest-800;\n\n\t.page-home .overlay {\n\t\tbackground-color: rgba($forest-900, 0.97);\n\t}\n\n\t.page-title {\n\t\th2 {\n\t\t\tcolor: $light;\n\t\t}\n\n\t\t.title-bg {\n\t\t\tcolor: rgba($sage, 0.06);\n\t\t}\n\t}\n\n\t.section-title h3::before {\n\t\tbackground-color: $light;\n\t}\n\n\th1,\n\th2,\n\th3,\n\th4,\n\th5,\n\th6,\n\t.about-author .author-desc p {\n\t\tcolor: $light;\n\t}\n\t.switcher-body h4 {\n\t\tcolor: $forest-800;\n\t}\n\n\t.service-hex {\n\t\t.st0 {\n\t\t\tfill: transparent;\n\t\t}\n\n\t\t&:hover {\n\t\t\t.st0 {\n\t\t\t\tfill: $light;\n\t\t\t}\n\t\t}\n\t}\n\n\t.testimonials .text,\n\t.btn-border {\n\t\tborder-color: $forest-700;\n\t}\n}"]}